<?php
require_once 'config.php';require_role('admin');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare('SELECT a.resume,u.name FROM applications a JOIN users u ON u.id=a.user_id JOIN jobs j ON j.id=a.job_id WHERE a.id=? AND j.posted_by=?');$s->execute([$id?:0,current_user()['id']]);$row=$s->fetch();if(!$row){http_response_code(404);exit('Resume not found.');}$path=__DIR__.'/uploads/resumes/'.$row['resume'];if(!is_file($path)){http_response_code(404);exit('Resume file not found.');}$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$types=['pdf'=>'application/pdf','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];header('Content-Type: '.($types[$ext]??'application/octet-stream'));header('Content-Disposition: attachment; filename="resume-'.$id.'.'.$ext.'"');header('Content-Length: '.filesize($path));readfile($path);exit;
